import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.C2TvIV46.js";const i=JSON.parse('{"title":"Megalo の頭痛の種","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/megalo-headaches.md","filePath":"ja/language/megalo-headaches.md"}'),o={name:"ja/language/megalo-headaches.md"};function l(p,a,c,d,r,m){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="megalo-の頭痛の種" tabindex="-1">Megalo の頭痛の種 <a class="header-anchor" href="#megalo-の頭痛の種" aria-label="Permalink to &quot;Megalo の頭痛の種&quot;">​</a></h1><p>ゲームタイプを書くときに出会うかもしれない、予期しない挙動を起こす Megalo の奇妙な点です。</p><h2 id="_1-壊れた変数シャドーイング" tabindex="-1">1. 壊れた変数シャドーイング <a class="header-anchor" href="#_1-壊れた変数シャドーイング" aria-label="Permalink to &quot;1. 壊れた変数シャドーイング&quot;">​</a></h2><p>MegaloEdit は重複名の変数定義を許しますが、一部の変数型は <strong>常に最初の宣言</strong> を参照するため、後続の宣言は静かに参照不能になり、ゲームタイプのスロットを無駄にします。</p><h3 id="影響あり-最初の宣言が勝つ" tabindex="-1">影響あり（最初の宣言が勝つ） <a class="header-anchor" href="#影響あり-最初の宣言が勝つ" aria-label="Permalink to &quot;影響あり（最初の宣言が勝つ）&quot;">​</a></h3><p>同じ名前を再宣言しても、名前解決では <strong>最初</strong> の宣言が残ります。後続の宣言もスロットは消費しますが、参照解決時には無視されます。</p><p><strong>変数</strong></p><table tabindex="0"><thead><tr><th>スコープ</th><th>型</th></tr></thead><tbody><tr><td><code>variables global</code></td><td><code>timer</code> のみ</td></tr><tr><td><code>variables player</code></td><td><code>number</code>、<code>timer</code>、<code>object</code>、<code>player</code>、<code>team</code></td></tr><tr><td><code>variables team</code></td><td><code>number</code>、<code>timer</code>、<code>object</code>、<code>player</code>、<code>team</code></td></tr><tr><td><code>variables object</code></td><td><code>number</code>、<code>timer</code>、<code>object</code>、<code>player</code>、<code>team</code></td></tr></tbody></table><p><strong>名前付き宣言</strong>（同じ append + <code>FindIndex</code> パターン）</p><table tabindex="0"><thead><tr><th>要素</th><th>名前</th></tr></thead><tbody><tr><td><code>map_object</code></td><td>フィルタ名</td></tr><tr><td><code>game_options</code></td><td><code>option</code> / <code>ranged_option</code> 名</td></tr><tr><td><code>game_options</code></td><td><code>player_traits</code> 受取人名</td></tr><tr><td><code>game_stats</code></td><td>統計名</td></tr><tr><td><code>hud_widgets</code></td><td>ウィジェット名</td></tr><tr><td><code>loadout</code></td><td>ロードアウト名</td></tr><tr><td><code>loadout_palette</code></td><td>パレット名</td></tr><tr><td><code>requisition_palette</code></td><td>パレット名</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">timer</span><span class="megalo-text"> </span><span class="megalo-variable">shared_timer</span><span class="megalo-text"> </span><span class="megalo-number">5</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">timer</span><span class="megalo-text"> </span><span class="megalo-variable">shared_timer</span><span class="megalo-text"> </span><span class="megalo-number">99</span><span class="megalo-text">   </span><span class="megalo-comment">; slot taken, but name still means the first</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">flag</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">flag</span><span class="megalo-text"> </span><span class="megalo-number">1</span><span class="megalo-text">               </span><span class="megalo-comment">; same: first \`flag\` wins</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">map_object</span><span class="megalo-text"> </span><span class="megalo-variable">shared_filter</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">label</span><span class="megalo-text"> </span><span class="megalo-string">&quot;first&quot;</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">map_object</span><span class="megalo-text"> </span><span class="megalo-variable">shared_filter</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">label</span><span class="megalo-text"> </span><span class="megalo-string">&quot;second&quot;</span><span class="megalo-text">                    </span><span class="megalo-comment">; slot taken; references resolve to the first</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h3 id="影響なし-最後の宣言が勝つ" tabindex="-1">影響なし（最後の宣言が勝つ） <a class="header-anchor" href="#影響なし-最後の宣言が勝つ" aria-label="Permalink to &quot;影響なし（最後の宣言が勝つ）&quot;">​</a></h3><p>これらは <code>FindLastIndex</code> を使うため、同じ名前の後続宣言が名前解決で正しく前のものをシャドーします（両方ともスロットは消費します）。</p><table tabindex="0"><thead><tr><th>スコープ</th><th>型</th></tr></thead><tbody><tr><td><code>variables global</code></td><td><code>number</code>、<code>object</code>、<code>player</code>、<code>team</code></td></tr><tr><td>一時変数</td><td>すべての型（トリガー内の <code>temporary</code>）</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">counter</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">counter</span><span class="megalo-text"> </span><span class="megalo-number">7</span><span class="megalo-text">            </span><span class="megalo-comment">; references resolve to this one</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>文字列は別ケースです。MegaloEdit は同じ言語内の重複文字列名に対してシャドーせず <strong>エラー</strong> にします。</p><h2 id="_2-アクセスできない-target-team" tabindex="-1">2. アクセスできない <code>target_team</code> <a class="header-anchor" href="#_2-アクセスできない-target-team" aria-label="Permalink to &quot;2. アクセスできない \`target_team\`&quot;">​</a></h2><p>エンジンは <a href="/MegaloEvolved/beta/docs/ja/language/references#context-references"><code>target_player</code></a> を所有するチーム用の明示的なチームスロット（ワイヤ上の <code>ExplicitTeam.TargetTeam</code>）を公開しています。MegaloEdit のオートコンプリートは <code>target_team</code> さえ一覧に出しますが、チームパーサーは HUD のローカルプレイヤー所有チームとして <code>local_team</code> だけを受け付け — <code>target_team</code>（または古い別名 <code>hud_target_player_owner_team</code>）には一致しません。</p><p>したがって MegaloEdit では次を書けません。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set some_team set_to target_team</span></span></code></pre></div><p>この参照は死んだキーワードです。オートコンプリートとバイナリエンコーディングにはあるが、パースにはありません。</p><h2 id="_3-アクセスできない-coop-spawning-ナビポイントアイコン" tabindex="-1">3. アクセスできない <code>coop spawning</code> ナビポイントアイコン <a class="header-anchor" href="#_3-アクセスできない-coop-spawning-ナビポイントアイコン" aria-label="Permalink to &quot;3. アクセスできない \`coop spawning\` ナビポイントアイコン&quot;">​</a></h2><p><code>navpoint_set_icon</code> の名前テーブルには、文字列が文字どおり <strong><code>coop spawning</code></strong>（スペース付き）の最終エントリがあります。</p><p>MegaloEdit はアイコン名を <code>read_enumerated_string</code> で解決し、これは <strong>1 つ</strong> の識別子トークンを消費して各テーブル文字列と比較します。1 トークンでは <code>&quot;coop spawning&quot;</code> と等しくなり得ないため、このアイコンは書けません。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action navpoint_set_icon marker coop spawning   </span><span class="megalo-comment">; never matches</span></span></code></pre></div>`,25)])])}const b=e(o,[["render",l]]);export{i as __pageData,b as default};
